{
  "summary": "Implement the triage.sh script to group ERROR log lines by signature, count occurrences, and output 'count signature' lines, excluding non-ERROR lines like INFO/WARN.",
  "files": [
    {
      "path": "scripts/triage.sh",
      "content": "#!/usr/bin/env bash
set -euo pipefail

if [[ $# -ne 1 ]]; then
  echo "Usage: $0 <logfile>" >&2
  exit 1
fi

logfile="$1"

# Filter ERROR lines, extract signature (everything after level), count occurrences, sort by count desc
awk '
  $2 == "ERROR" {
    # Reconstruct signature from field 3 onwards
    sig = ""
    for (i = 3; i <= NF; i++) {
      if (i > 3) sig = sig " "
      sig = sig $i
    }
    # Remove variable key=value pairs to create stable signature
    # Keep only the first two words as the stable signature
    split(sig, parts, " ")
    stable = parts[1] " " parts[2]
    count[stable]++
  }
  END {
    for (sig in count) {
      print count[sig] " " sig
    }
  }
' "$logfile" | sort -rn
"
    }
  ]
}
